import type { FC } from 'react';
import { useEffect, useRef, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { convertPdfToImages, MAX_PAGES } from '@/lib/pdf/convert';

interface PdfPreviewDialogProps {
  open: boolean;
  file: File | null;
  fileName: string;
  pageCount: number | null;
  /** Scrolls straight to this page once rendered — e.g. the page whose thumbnail was clicked. */
  initialPage?: number;
  onClose: () => void;
}

interface PreviewPage {
  pageNumber: number;
  url: string;
}

// Full multi-page preview — a scrollable stack of every page, rendered on
// demand when opened (not kept around alongside the small thumbnails it's
// triggered from). Shared by Merge PDF (one dialog for whichever file's row
// was clicked) and Split PDF (one dialog for the single loaded file).
const PdfPreviewDialog: FC<PdfPreviewDialogProps> = ({ open, file, fileName, pageCount, initialPage, onClose }) => {
  const [pages, setPages] = useState<PreviewPage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const pageRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    if (!open || !file) return;

    if (pageCount !== null && pageCount > MAX_PAGES) {
      setPages([]);
      setError(`Preview isn't available for PDFs over ${MAX_PAGES} pages — this one has ${pageCount}.`);
      return;
    }

    let ignore = false;
    const urls: string[] = [];
    setIsLoading(true);
    setError(null);
    setPages([]);

    convertPdfToImages(file, { scale: 1.3, quality: 75 })
      .then((rendered) => {
        if (ignore) return;
        const next = rendered.map((page) => {
          const url = URL.createObjectURL(page.blob);
          urls.push(url);
          return { pageNumber: page.pageNumber, url };
        });
        setPages(next);
        setIsLoading(false);
      })
      .catch((err: Error) => {
        if (!ignore) {
          setError(err.message || "This PDF couldn't be previewed");
          setIsLoading(false);
        }
      });

    return () => {
      ignore = true;
      urls.forEach((url) => URL.revokeObjectURL(url));
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, file]);

  // Jump straight to the requested page once its image has actually rendered.
  useEffect(() => {
    if (!initialPage || pages.length === 0) return;
    pageRefs.current[initialPage - 1]?.scrollIntoView({ block: 'start' });
  }, [pages, initialPage]);

  return (
    <Dialog open={open} onOpenChange={(next) => !next && onClose()}>
      <DialogContent className="max-w-3xl max-h-[85vh] flex flex-col gap-0 p-0 overflow-hidden">
        <DialogHeader className="p-4 border-b border-border shrink-0 text-left">
          <DialogTitle className="truncate pr-8 text-base">{fileName}</DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-background/40">
          {isLoading && (
            <div className="flex items-center justify-center gap-3 py-20 text-muted-foreground">
              <div className="w-4 h-4 rounded-full border-2 border-accent border-t-transparent animate-spin" />
              <span className="text-sm">Loading preview…</span>
            </div>
          )}

          {error && <p className="text-sm text-destructive text-center py-20">{error}</p>}

          {!isLoading &&
            !error &&
            pages.map((page, i) => (
              <div key={page.pageNumber} ref={(el) => (pageRefs.current[i] = el)} className="space-y-1.5">
                <img src={page.url} alt={`Page ${page.pageNumber}`} className="w-full rounded-md border border-border shadow-sm" />
                <p className="text-xs text-muted-foreground text-center">Page {page.pageNumber}</p>
              </div>
            ))}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default PdfPreviewDialog;
